-- 303: Original BrillaPrep WASSCE BrillaPrep transitional Clerical Office Duties beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_303_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_303_guard;
INSERT INTO _migration_303_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_011' AND NOT (q.topic_id IS 'topic_was_clerical_b005_3' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should be done first when incoming business mail is received?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To record outgoing items and provide evidence of when and how they were sent","B. When proof of posting and delivery is important","C. Check, date-stamp and sort it according to the organisation’s procedure","D. A telephone or live call followed by a written record where necessary"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Controlled receipt records arrival and routes correspondence without losing urgent, private or wrongly addressed items. Therefore the correct answer is C: Check, date-stamp and sort it according to the organisation’s procedure.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_011' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_303_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_012' AND NOT (q.topic_id IS 'topic_was_clerical_b005_3' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a dispatch register maintained?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. When proof of posting and delivery is important","B. A telephone or live call followed by a written record where necessary","C. To route the call accurately while protecting staff time and information","D. To record outgoing items and provide evidence of when and how they were sent"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A dispatch record supports tracking, follow-up and accountability for important correspondence and parcels. Therefore the correct answer is D: To record outgoing items and provide evidence of when and how they were sent.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_012' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_303_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_013' AND NOT (q.topic_id IS 'topic_was_clerical_b005_3' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When is registered or tracked delivery preferable to ordinary post?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. When proof of posting and delivery is important","B. A telephone or live call followed by a written record where necessary","C. To route the call accurately while protecting staff time and information","D. Check, date-stamp and sort it according to the organisation’s procedure"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tracking and acknowledgement provide evidence for valuable, confidential or time-sensitive items that ordinary mail cannot supply. Therefore the correct answer is A: When proof of posting and delivery is important.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_013' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_303_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_014' AND NOT (q.topic_id IS 'topic_was_clerical_b005_3' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which communication channel is most suitable for an urgent issue requiring immediate clarification?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To route the call accurately while protecting staff time and information","B. A telephone or live call followed by a written record where necessary","C. Check, date-stamp and sort it according to the organisation’s procedure","D. To record outgoing items and provide evidence of when and how they were sent"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A live call permits rapid two-way clarification, while a follow-up note can preserve decisions and responsibilities. Therefore the correct answer is B: A telephone or live call followed by a written record where necessary.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_014' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_303_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_015' AND NOT (q.topic_id IS 'topic_was_clerical_b005_3' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a receptionist confirm the purpose of a caller before transferring the call?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Check, date-stamp and sort it according to the organisation’s procedure","B. To record outgoing items and provide evidence of when and how they were sent","C. To route the call accurately while protecting staff time and information","D. When proof of posting and delivery is important"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Appropriate screening improves service, avoids repeated transfers and prevents unnecessary disclosure of internal details. Therefore the correct answer is C: To route the call accurately while protecting staff time and information.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_015' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_clerical_b005_011', 'topic_was_clerical_b005_3', 'subj_wassce_clerical', 'exam_wassce', NULL, NULL, 'What should be done first when incoming business mail is received?', 'multiple_choice', NULL, '["A. To record outgoing items and provide evidence of when and how they were sent","B. When proof of posting and delivery is important","C. Check, date-stamp and sort it according to the organisation’s procedure","D. A telephone or live call followed by a written record where necessary"]', 'C', 'Controlled receipt records arrival and routes correspondence without losing urgent, private or wrongly addressed items. Therefore the correct answer is C: Check, date-stamp and sort it according to the organisation’s procedure.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_clerical_b005_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
