INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_clerical_b005_013', 'topic_was_clerical_b005_3', 'subj_wassce_clerical', 'exam_wassce', NULL, NULL, 'When is registered or tracked delivery preferable to ordinary post?', 'multiple_choice', NULL, '["A. When proof of posting and delivery is important","B. A telephone or live call followed by a written record where necessary","C. To route the call accurately while protecting staff time and information","D. Check, date-stamp and sort it according to the organisation’s procedure"]', 'A', 'Tracking and acknowledgement provide evidence for valuable, confidential or time-sensitive items that ordinary mail cannot supply. Therefore the correct answer is A: When proof of posting and delivery is important.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_clerical_b005_3', 'Identify', 'AO1', NULL, NULL, 'board_waec');
